function serversNeeded(dau, requestsPerUser, peakFactor, qpsPerServer, targetUtilization) {
  const avgQps = (dau * requestsPerUser) / 86_400;
  const peakQps = avgQps * peakFactor;
  const usablePerServer = qpsPerServer * targetUtilization;
  return Math.ceil(peakQps / usablePerServer);
}

serversNeeded(10e6, 30, 3, 2000, 0.6); // avg ≈ 3,472, peak ≈ 10,417, usable 1,200 → 9
```
Note: `10e6 × 30 / 86,400 ≈ 3,472`, `× 3 ≈ 10,417`, `/ 1,200 ≈ 8.7 → 9` servers. Add one or two more so a single failure doesn't overload the rest.
